import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"CEFR Goals and English Self-check","description":"Use A1-C2 can-do descriptors to establish a four-skill baseline and turn it into verifiable 7-day, 30-day, and 12-week work.","frontmatter":{"title":"CEFR Goals and English Self-check","description":"Use A1-C2 can-do descriptors to establish a four-skill baseline and turn it into verifiable 7-day, 30-day, and 12-week work.","updated":"2026-10-06T00:00:00.000Z"},"headers":[],"relativePath":"en/threads/part-1/0-cefr.md","filePath":"en/threads/part-1/0-cefr.md","lastUpdated":1791244800000}'),i={name:"en/threads/part-1/0-cefr.md"};function o(s,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="cefr-goals-and-english-self-check" tabindex="-1">CEFR Goals and English Self-check <a class="header-anchor" href="#cefr-goals-and-english-self-check" aria-label="Permalink to &quot;CEFR Goals and English Self-check&quot;">​</a></h1><p>The CEFR describes <strong>what a person can do with language in context</strong>. It is not an app score or a fixed vocabulary count. This page simplifies the Council of Europe global scale to help you choose a starting point; it does not replace a formal assessment.</p><h2 id="quick-overview" tabindex="-1">Quick Overview <a class="header-anchor" href="#quick-overview" aria-label="Permalink to &quot;Quick Overview&quot;">​</a></h2><ul><li>save an unpolished baseline for listening, speaking, reading, and writing separately;</li><li>translate an A1–C2 direction into a context, task, quality threshold, and deadline;</li><li>use seven-day, thirty-day, and twelve-week rhythms instead of chasing one average level;</li><li>retest under comparable conditions with a parallel task and outside feedback before choosing the next variable.</li></ul><h2 id="a1-c2-what-can-i-do" tabindex="-1">A1-C2: What Can I Do? <a class="header-anchor" href="#a1-c2-what-can-i-do" aria-label="Permalink to &quot;A1-C2: What Can I Do?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Observable overall performance</th></tr></thead><tbody><tr><td>A1</td><td>Understand and use very common expressions; interact simply when the other person speaks slowly and helps.</td></tr><tr><td>A2</td><td>Handle direct exchanges about familiar matters such as personal information, shopping, places, and work.</td></tr><tr><td>B1</td><td>Understand the main points on familiar matters; handle most travel situations and briefly explain experiences, plans, and reasons.</td></tr><tr><td>B2</td><td>Understand main ideas in complex concrete or abstract texts; interact fairly naturally and explain a viewpoint clearly.</td></tr><tr><td>C1</td><td>Understand demanding, longer material and implicit meaning; use language flexibly in social, academic, and professional settings.</td></tr><tr><td>C2</td><td>Understand almost everything heard or read with ease; synthesize sources, reconstruct arguments, and express fine distinctions precisely.</td></tr></tbody></table><p>Source: <a href="https://www.coe.int/en/web/common-european-framework-reference-languages/table-1-cefr-3.3-common-reference-levels-global-scale" target="_blank" rel="noreferrer">Council of Europe, CEFR 3.3 Global Scale</a>, accessed 2026-08-16. These are action-oriented summaries, not the official wording.</p><h2 id="four-skill-evidence" tabindex="-1">Four-skill Evidence <a class="header-anchor" href="#four-skill-evidence" aria-label="Permalink to &quot;Four-skill Evidence&quot;">​</a></h2><p>Choose one topic connected to real life. Complete the first version without looking things up and keep the raw sample.</p><table tabindex="0"><thead><tr><th>Skill</th><th>10–20 minute task</th><th>Check</th></tr></thead><tbody><tr><td>Listening</td><td>Hear 2–4 minutes; record the main point, three details, and a retelling</td><td>Gist, detail, chunk boundaries, causes of misses</td></tr><tr><td>Reading</td><td>Read 600–1000 words; write five summary sentences and one challenge</td><td>Claim, evidence, inference, whether unknown words block meaning</td></tr><tr><td>Speaking</td><td>Record an unscripted two-minute explanation</td><td>Intelligibility, pauses, grammar, chunks, task completion</td></tr><tr><td>Writing</td><td>Write a 180–250 word email, explanation, or argument in 20 minutes</td><td>Purpose, structure, support, accuracy, revision</td></tr></tbody></table><p>Save the samples in the <a href="./../../templates/english-diagnostic">English Diagnostic</a>. Rate each skill separately when the profile is uneven.</p><h2 id="do-not-let-a-four-skill-average-hide-collaboration" tabindex="-1">Do Not Let a Four-skill Average Hide Collaboration <a class="header-anchor" href="#do-not-let-a-four-skill-average-hide-collaboration" aria-label="Permalink to &quot;Do Not Let a Four-skill Average Hide Collaboration&quot;">​</a></h2><p>Listening, reading, speaking, and writing are necessary entry points, but real study and work also require you to pass information to other people, move an asynchronous conversation forward, and repair misunderstandings when they appear. These are <strong>task dimensions</strong>, not an extra level outside A1–C2; record their evidence separately on the same diagnostic page.</p><table tabindex="0"><thead><tr><th>Task dimension</th><th>10–15 minute sample</th><th>Evidence of completion</th></tr></thead><tbody><tr><td>Mediation and retelling</td><td>Read two short texts with different positions and explain each claim, the difference, and what remains unknown</td><td>A listener can distinguish both views, your retelling, and your inference; conflict is not smoothed into agreement</td></tr><tr><td>Online interaction</td><td>In a real or simulated asynchronous thread, write one progress update, one blocker, and the next step</td><td>The other person knows who owns the next action, when it can continue, and what information is missing without a meeting</td></tr><tr><td>Repairing misunderstanding</td><td>Ask for clarification in a conversation, then restate the shared understanding and open questions</td><td>The other person confirms the restatement, and the next action does not change because of a guess</td></tr></tbody></table><p>Skip a dimension if your course, role, or family collaboration rarely uses it; test it separately when it is a high-risk part of real life. Do not use a speaking or writing score as a substitute. For role-specific samples, continue to <a href="./8-job-search-english">Job-search English</a> and place these dimensions back into a real job description and evidence card.</p><h2 id="turn-a-level-into-a-goal" tabindex="-1">Turn a Level into a Goal <a class="header-anchor" href="#turn-a-level-into-a-goal" aria-label="Permalink to &quot;Turn a Level into a Goal&quot;">​</a></h2><p>A useful goal contains a <strong>context, task, quality threshold, deadline, and evidence</strong>.</p><blockquote><p>In 12 weeks, I can deliver a five-minute project update covering context, progress, and risk. Listeners can restate the key points without switching language. I will keep recordings and feedback from weeks 1, 4, 8, and 12.</p></blockquote><p>“Move from B1 to B2” is a direction, not a complete training goal. Progress is rarely linear and cannot be guaranteed by hours alone.</p><p>When the real goal is a global role or remote interview, do not turn B1, B2, or C1 into a universal hiring line. Continue to <a href="./8-job-search-english">Job-search English</a>, test project explanation, unfamiliar follow-up, repair, and asynchronous writing against one real role, then let the component evidence choose the next variable.</p><h2 id="seven-day-start" tabindex="-1">Seven-day Start <a class="header-anchor" href="#seven-day-start" aria-label="Permalink to &quot;Seven-day Start&quot;">​</a></h2><ul><li>Day 1: complete four baselines and save the unpolished samples.</li><li>Days 2–5: choose one skill daily for 25–45 minutes of input, retrieval, output, and feedback.</li><li>Day 6: repeat the weakest task and compare error categories.</li><li>Day 7: complete the <a href="./../../templates/weekly-review">Weekly Review</a> and choose one focus.</li></ul><h2 id="thirty-day-system" tabindex="-1">Thirty-day System <a class="header-anchor" href="#thirty-day-system" aria-label="Permalink to &quot;Thirty-day System&quot;">​</a></h2><ul><li>Complete at least one inspectable task in each skill every week; repeat the priority skill more often.</li><li>Classify errors as comprehension, vocabulary/chunks, pronunciation, grammar, structure, strategy, or attention.</li><li>Repeat an old task or a parallel task weekly and compare performance rather than feeling.</li><li>On day 30, repeat the baseline conditions and keep both samples plus external feedback.</li></ul><h2 id="twelve-week-transfer" tabindex="-1">Twelve-week Transfer <a class="header-anchor" href="#twelve-week-transfer" aria-label="Permalink to &quot;Twelve-week Transfer&quot;">​</a></h2><ul><li>Weeks 1–4: establish rhythm with tasks below the frustration threshold.</li><li>Weeks 5–8: increase complexity and time pressure; transfer across topics.</li><li>Weeks 9–11: simulate the real exam, meeting, presentation, reading, or writing deliverable.</li><li>Week 12: complete the final task, obtain a blind or real-audience review, and choose the next cycle.</li></ul><h2 id="feedback-rubric" tabindex="-1">Feedback Rubric <a class="header-anchor" href="#feedback-rubric" aria-label="Permalink to &quot;Feedback Rubric&quot;">​</a></h2><p>Score each <code>0=not completed</code>, <code>1=partly</code>, or <code>2=consistently</code>:</p><ol><li><strong>Task completion</strong>: did the intended information and purpose arrive?</li><li><strong>Comprehensibility</strong>: could the audience understand without guessing?</li><li><strong>Accuracy and range</strong>: did language choices support the task?</li><li><strong>Organisation and fluency</strong>: was the message coherent without disruptive pauses?</li><li><strong>Revision and transfer</strong>: could you improve from feedback and reuse it in a new task?</li></ol><p>Use totals only for your own longitudinal comparison, never as a label for another person.</p><p>When accuracy and range remain weak, do not call every problem “bad grammar”. First ask whether the choice changes time, participants, negation, condition, or certainty, then use <a href="./grammar">Grammar</a> and the <a href="./../../templates/grammar-evidence">Grammar Evidence Card</a> to track one structure that affects the task. Lower-impact variation can wait.</p><h2 id="carry-the-self-check-into-the-next-cycle" tabindex="-1">Carry the Self-check into the Next Cycle <a class="header-anchor" href="#carry-the-self-check-into-the-next-cycle" aria-label="Permalink to &quot;Carry the Self-check into the Next Cycle&quot;">​</a></h2><p>This rubric describes performance in one task; it does not announce that you have “reached a level”. After the self-check, carry the result into <a href="./../part-3/5-evidence-and-transfer">Evidence: How Change Becomes Visible</a>:</p><ol><li>Save today&#39;s baseline instead of replacing it with the revised version;</li><li>record immediate performance after practice and what help you received;</li><li>remove the recent prompts and retest delayed retention after seven days;</li><li>change the topic, audience, or task after thirty or ninety days to check transfer.</li></ol><p>When the four skills differ, track separate evidence chains. The value of a self-check is not a flattering label. It gives the next practice a point that can be compared.</p><p>Use the <a href="./../../templates/evidence-chain">Evidence Chain Template</a> to keep the four time points together instead of preserving only a final score.</p><h2 id="closing-a-level-is-only-a-coordinate" tabindex="-1">Closing: A Level Is Only a Coordinate <a class="header-anchor" href="#closing-a-level-is-only-a-coordinate" aria-label="Permalink to &quot;Closing: A Level Is Only a Coordinate&quot;">​</a></h2><p>A level can suggest how far away a task may be. It cannot tell you why the journey matters, and it cannot travel for you. A2, B1, or C1 describes performance under particular conditions. It is not the limit of a person, or a certificate of who deserves to be heard, trusted, or loved.</p><p>Real change is often quieter than a changed label: the first time you understand a stranger&#39;s request, finish explaining your reason in a meeting, or write an email the other person does not have to decipher. The label may remain where it was, while another usable road has already opened between you and the world.</p><p>Keep today&#39;s score, and keep today&#39;s awkwardness too. When you return, do not ask whether you finally deserve a letter. Ask which real task you can now complete more fully. A coordinate should help a person find a road, not pin them to the ground.</p>',40)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
